const textOf = v => v == null ? '' : Array.isArray(v) ? v.map(textOf).join('') :
  typeof v === 'object' ? textOf(v.text ?? v.name ?? v.value) : String(v).trim();
const str = (fields, ...keys) => keys.map(key=>textOf(fields[key])).find(Boolean) || '';
function parseRows(table, records) {
  const [source, tableId] = table;
  const normal = records.map(r=>({id:r.record_id, fields:r.fields||{}}));
  const header = normal.find(r=>{
    const labels=Object.values(r.fields).map(textOf);
    return names.some(n=>labels.includes(n)) && labels.includes('拟匹配职位');
  });
  const mapping = header ? Object.fromEntries(Object.entries(header.fields).map(([k,v])=>[k,textOf(v)])) : null;
  if (!header && normal.length && !normal.some(r=>names.some(k=>Object.hasOwn(r.fields,k)))) throw Error('schema');
  const people=[];
  for(const r of normal){
    if(r===header)continue;
    const f = mapping ? Object.fromEntries(Object.entries(r.fields).filter(([k])=>mapping[k]).map(([k,v])=>[mapping[k],v])) : r.fields;
    const name=str(f,...names);
    if(!name || /^[\d\s.,]+$/.test(name) || names.includes(name) || ['合计','总计','小计'].includes(name))continue;
    const role=str(f,'拟匹配职位','拟匹配岗位','应聘岗位'),team=str(f,'拟匹配部门','部门');
    const workplace=str(f,'岗位Base地','岗位 Base 地','工作地点','岗位地','Base地','Base 地');
    const category=source==='商务准入政务待面'?'商务准入政务岗位':source==='职能待面'?'职能岗位':/市场/.test(team)?'市场岗位':/医学/.test(team)?'医学岗位':/销售|营销/.test(team)?'营销岗位':'其他岗位';
    people.push({id:tableId+'_'+r.id,name,role,team,category,source,base:workplace.replace(/[（(]\s*人在[^)）]*[)）]/g,'').trim(),
      proposedMarket:str(f,'拟定市场'),company:str(f,'目前公司'),current:str(f,'目前职位'),round:str(f,'预计终面时间')});
  }
  return people;
}
class FeishuFailure extends Error {
  constructor(message,status=422){super(message);this.status=status;}
}
const tokenPath='auth/v3/tenant_access_token/internal';
async function api(path,init,stage) {
  let res,body;
  try{
    res=await fetch('https://open.feishu.cn/open-apis/'+path,{...init,redirect:'manual',signal:AbortSignal.timeout(15000)});
  }catch(e){
    const timedOut=e.name==='TimeoutError'||e.name==='AbortError';
    throw new FeishuFailure(stage+(timedOut?'时连接飞书超时。':'时网站未能连接飞书服务。'),502);
  }
  if(res.status>=300&&res.status<400)throw new FeishuFailure(stage+'时飞书接口返回重定向，请检查服务地址。',502);
  try{body=await res.json()}catch{throw new FeishuFailure(stage+'时上游返回了非 JSON 响应（HTTP '+res.status+'）。',502)}
  if(!res.ok||body.code!==0){
    const code=Number.isSafeInteger(body.code)?String(body.code):'HTTP '+res.status;
    const hint=stage==='验证应用'?'请核对同一应用的 App ID 和当前 App Secret。':'请核对机器人对该视图的读取权限。';
    throw new FeishuFailure(stage+'失败（'+code+'）。'+hint);
  }
  return body;
}
async function checkFeishuReachability(){
  try{
    await api(tokenPath,{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'},'验证应用');
  }catch(e){
    if(e instanceof FeishuFailure && e.status===422 && /（\d+）/.test(e.message))
      return {reachable:true,feishuCode:Number(e.message.match(/（(\d+)）/)[1])};
    return {reachable:false,reason:e instanceof FeishuFailure?e.message:'服务端测试失败'};
  }
  return {reachable:true};
}
async function fetchView(table,token) {
  let next='', all=[];const seen=new Set();
  do{
    const params=new URLSearchParams({page_size:'500',view_id:table[2]});
    if(next)params.set('page_token',next);
    const resp=await api('bitable/v1/apps/'+BASE+'/tables/'+table[1]+'/records?'+params,{headers:{Authorization:'Bearer '+token}},'读取「'+table[0]+'」');
    if(!Array.isArray(resp.data?.items))throw new FeishuFailure('「'+table[0]+'」返回的记录格式有变化，需要核对视图。',502);
    all.push(...resp.data.items);
    next=resp.data.has_more?resp.data.page_token:'';
    if((resp.data.has_more&&!next)||(next&&seen.has(next)))throw new FeishuFailure('「'+table[0]+'」未返回完整记录，请稍后重试。',502);
    seen.add(next);
  }while(next);
  try{return parseRows(table,all)}catch{throw new FeishuFailure('「'+table[0]+'」未识别到姓名列，请核对表头。')}
}
async function readLive(creds) {
  const auth=await api(tokenPath,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({app_id:creds.id,app_secret:creds.secret})},'验证应用');
  if(!auth.tenant_access_token)throw new FeishuFailure('飞书未返回应用访问凭证，请核对应用状态。');
  const groups=await Promise.all(TABLES.map(t=>fetchView(t,auth.tenant_access_token)));
  return {at:new Date().toISOString(),people:groups.flat(),source:'live'};
}


const noStore={'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Referrer-Policy':'no-referrer'};
const json=(obj,status=200)=>new Response(JSON.stringify(obj),{status,headers:{...noStore,'Content-Type':'application/json; charset=utf-8'}});
const bytes=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const b64=data=>btoa(String.fromCharCode(...new Uint8Array(data)));
async function aesKey(env) {return crypto.subtle.importKey('raw',bytes(env.CONNECTION_KEY),'AES-GCM',false,['encrypt','decrypt']);}
async function seal(env,credentials){
  const iv=crypto.getRandomValues(new Uint8Array(12));
  const encrypted=await crypto.subtle.encrypt({name:'AES-GCM',iv},await aesKey(env),new TextEncoder().encode(JSON.stringify(credentials)));
  return JSON.stringify({iv:b64(iv),cipher:b64(encrypted)});
}
async function retrieveCredentials(env) {
  if(env.FEISHU_APP_ID&&env.FEISHU_APP_SECRET)return {id:env.FEISHU_APP_ID,secret:env.FEISHU_APP_SECRET};
  if(!env.BUCKET || !env.CONNECTION_KEY)return null;
  const obj=await env.BUCKET.get('connection-v1');
  if(!obj)return null;
  const config=await obj.json();
  const raw=await crypto.subtle.decrypt({name:'AES-GCM',iv:bytes(config.iv)},await aesKey(env),bytes(config.cipher));
  return JSON.parse(new TextDecoder().decode(raw));
}
let seedMemo, inFlight, lastGood;
async function baseline(env){
  if(seedMemo)return seedMemo;
  const parts=[env.INTERVIEW_BOOTSTRAP_1,env.INTERVIEW_BOOTSTRAP_2,env.INTERVIEW_BOOTSTRAP_3,env.INTERVIEW_BOOTSTRAP_4].filter(Boolean);
  if(!parts.length)return null;
  const stream=new Response(bytes(parts.join(''))).body.pipeThrough(new DecompressionStream('gzip'));
  seedMemo=await new Response(stream).json();return seedMemo;
}
async function latest(env){
  let saved=null;
  try{const file=await env.BUCKET?.get('roster-v1');saved=file?await file.json():null;}catch{/* The checked baseline remains available during storage interruptions. */}
  if(saved&&(!lastGood||saved.at>lastGood.at))lastGood=saved;
  return lastGood||await baseline(env);
}
async function remember(env,snapshot){
  if(!lastGood||snapshot.at>=lastGood.at)lastGood=snapshot;
  if(env.BUCKET){
    // Conditional writes prevent a slower request from replacing newer data.
    const old=await env.BUCKET.head('roster-v1');
    if(!old||!old.customMetadata?.at||old.customMetadata.at<=snapshot.at){
      await env.BUCKET.put('roster-v1',JSON.stringify(snapshot),{onlyIf:old?{etagMatches:old.etag}:{etagDoesNotMatch:'*'},customMetadata:{at:snapshot.at},
        httpMetadata:{contentType:'application/json'}});
    }
  }
  return snapshot;
}
function owner(request,env){
  const email=request.headers.get('oai-authenticated-user-email')||'';
  return !!email&&!!env.INTERVIEW_OWNER&&email.toLowerCase()===env.INTERVIEW_OWNER.toLowerCase()&&!!request.headers.get('oai-authenticated-user-id');
}
async function getRoster(req,env) {
  const previous=await latest(env);
  const canConnect=owner(req,env)&&!!env.BUCKET&&!!env.CONNECTION_KEY;
  try {
    const creds=await retrieveCredentials(env);
    if(!creds)return json({snapshot:previous,state:'setup',canConnect});
    const force=owner(req,env)&&new URL(req.url).searchParams.get('refresh')==='1';
    if(!force&&previous?.source==='live'&&Date.now()-Date.parse(previous.at)<55000)
      return json({snapshot:previous,state:'live',canConnect});
    if(!inFlight)inFlight=readLive(creds).then(s=>remember(env,s)).finally(()=>{inFlight=null});
    return json({snapshot:await inFlight,state:'live',canConnect});
  }catch{return json({snapshot:previous,state:'stale',canConnect},previous?200:503)}
}
async function connect(req,env){
  if(!owner(req,env)||req.headers.get('Origin')!==new URL(req.url).origin)return json({error:'无权配置此站点'},403);
  if(!env.BUCKET||!env.CONNECTION_KEY)return json({error:'请在网站托管设置中配置飞书应用。'},503);
  if(!req.headers.get('Content-Type')?.includes('application/json'))return json({error:'请求格式有误'},400);
  let input;try{const raw=await req.text();if(raw.length>1500)return json({error:'参数过长'},400);input=JSON.parse(raw)}catch{return json({error:'参数无效'},400)}
  if(!/^cli_[a-zA-Z0-9]{6,64}$/.test(input.id||'')||typeof input.secret!=='string'||input.secret.length<12||input.secret.length>256)return json({error:'请检查 App ID 和 App Secret。'},400);
  try{
    const creds={id:input.id,secret:input.secret};const snap=await readLive(creds);
    await env.BUCKET.put('connection-v1',await seal(env,creds));
    await remember(env,snap);return json({snapshot:snap,state:'live',canConnect:true});
  }catch(e){
    if(e instanceof FeishuFailure)return json({error:e.message},e.status);
    return json({error:'未能保存连接结果，请稍后重试。'},503);
  }
}
export default {async fetch(request,env){
  const url=new URL(request.url);
  if(request.method==='GET' && (url.pathname==='/'||url.pathname==='/index.html') && url.searchParams.has('secret')){
    return new Response(null,{status:303,headers:{...noStore,Location:'/'}});
  }
  if(url.pathname==='/api/roster'||url.pathname==='/api/connection'||url.pathname==='/api/connection/reachability'){
    if(url.pathname==='/api/roster'&&request.method==='GET')return getRoster(request,env);
    const siteProbe=env.INTERVIEW_VERIFY&&request.headers.get('X-Interview-Verify')===env.INTERVIEW_VERIFY;
    if(!request.headers.get('oai-authenticated-user-id')&&!siteProbe)return json({error:'请登录面试工作台'},401);
    if(url.pathname==='/api/connection/reachability' && request.method==='GET'){
      if(!siteProbe&&!owner(request,env))return json({error:'无权测试连接'},403);
      const check=await checkFeishuReachability();
      return json(check,check.reachable?200:502);
    }
    if(url.pathname==='/api/connection'&&request.method==='POST')return connect(request,env);
    return json({error:'不支持此操作'},405);
  }
  if((url.pathname==='/'||url.pathname==='/index.html'||url.pathname==='/designs')&&request.method==='GET')return new Response(url.pathname==='/designs'?DESIGNS:PAGE,{headers:{...noStore,'Content-Type':'text/html; charset=utf-8','Content-Security-Policy':`default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'${url.pathname==='/designs'?'':" https://fonts.googleapis.com; font-src 'self' https://fonts.gstatic.com"}; connect-src 'self'; img-src 'self' data:; form-action 'none'; base-uri 'none'`}});
  return new Response(null,{status:404,headers:noStore});
}};

